import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { createLoggedSql, logCreate } from '@/lib/db-logger';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth } from '@/lib/auth';

// API response interface for stock items
interface StockItemResponse {
  id: string;
  itemCode: string;
  name: string;
  description: string;
  category: string;
  projectId: string;
  warehouse: string;
  location: string;
  quantity: number;
  unit: string;
  minQuantity: number;
  maxQuantity: number;
  unitCost: number;
  totalValue: number;
  supplier: string;
  lastRestocked: string;
  status: 'in_stock' | 'low_stock' | 'out_of_stock';
  createdAt: string;
  updatedAt: string;
}

// Initialize database connection with logging
const sql = createLoggedSql(process.env.DATABASE_URL!);

export default withAuth(withErrorHandler(async (
  req: NextApiRequest,
  res: NextApiResponse
) => {
  const { projectId } = req.query;

  if (req.method === 'GET') {
    try {
      // Query stock_items table (Odoo synced data)
      let movements = [];

      // Get all stock items from Odoo sync
      const stockData = await sql`
        SELECT
          id,
          item_code,
          name,
          description,
          category,
          qty_available,
          qty_reserved,
          qty_on_order,
          standard_cost,
          uom,
          min_stock_level,
          max_stock_level,
          odoo_product_id,
          odoo_synced_at,
          created_at,
          updated_at
        FROM stock_items
        ORDER BY name ASC
        LIMIT 500
      `;

      // Get recent movements with item details
      try {
        movements = await sql`
          SELECT
            sm.id,
            sm.reference_number,
            sm.movement_type,
            sm.from_location,
            sm.to_location,
            sm.status,
            sm.movement_date,
            sm.confirmed_at,
            sm.notes,
            sm.source_type,
            sm.odoo_picking_id,
            (
              SELECT COUNT(*) FROM stock_movement_items smi
              WHERE smi.stock_movement_id = sm.id
            ) as item_count,
            (
              SELECT COALESCE(SUM(smi.actual_quantity), 0) FROM stock_movement_items smi
              WHERE smi.stock_movement_id = sm.id
            ) as total_quantity
          FROM stock_movements sm
          ORDER BY sm.movement_date DESC
          LIMIT 50
        `;
      } catch {
        log.error('IndexApi', 'Operation failed', { error });
        // stock_movements table might not have data yet
        movements = [];
      }

      // Helper function to determine stock status
      const getStockStatus = (qty: number, minLevel: number): 'in_stock' | 'low_stock' | 'out_of_stock' => {
        if (qty === 0) return 'out_of_stock';
        if (minLevel > 0 && qty <= minLevel) return 'low_stock';
        return 'in_stock';
      };

      // Transform data to match expected format
      const transformedItems: StockItemResponse[] = stockData.map(stock => {
        const quantity = Number(stock.qty_available || 0);
        const minQuantity = Number(stock.min_stock_level || 0);
        const unitCost = Number(stock.standard_cost || 0);

        return {
          id: stock.id,
          itemCode: stock.item_code || '',
          name: stock.name || 'Unnamed Item',
          description: stock.description || '',
          category: stock.category || 'General',
          projectId: '', // Not project-specific in Odoo
          warehouse: 'Odoo Warehouse',
          location: '',
          quantity,
          unit: stock.uom || 'EA',
          minQuantity,
          maxQuantity: Number(stock.max_stock_level || 0),
          unitCost,
          totalValue: quantity * unitCost,
          supplier: '', // Would need supplier join
          lastRestocked: stock.odoo_synced_at || stock.updated_at || new Date().toISOString(),
          status: getStockStatus(quantity, minQuantity),
          createdAt: stock.created_at || new Date().toISOString(),
          updatedAt: stock.updated_at || new Date().toISOString(),
        };
      });

      // Calculate stock statistics
      const lowStockItems = transformedItems.filter(item =>
        item.status === 'low_stock' ||
        (item.minQuantity > 0 && item.quantity <= item.minQuantity)
      );

      const outOfStockItems = transformedItems.filter(item =>
        item.quantity === 0 || item.status === 'out_of_stock'
      );

      // Add movement statistics
      const movementStats = {
        recentMovements: movements.length,
        lastMovementDate: movements[0]?.movement_date || null,
        totalMovements: movements.length,
      };

      res.status(200).json({ 
        items: transformedItems,
        total: transformedItems.length,
        lowStock: lowStockItems.length,
        outOfStock: outOfStockItems.length,
        movements: movements.slice(0, 10),
        stats: {
          totalValue: transformedItems.reduce((sum, item) => sum + (item.totalValue || 0), 0),
          categories: [...new Set(transformedItems.map(item => item.category))],
          ...movementStats,
        }
      });
    } catch (error) {
      log.error('Error fetching stock items', { error, module: 'procurement:stock' });
      return apiResponse.internalError(res, error);
    }
  } else if (req.method === 'POST') {
    try {
      const newItem = req.body;

      // Insert new stock position into database
      const insertedStocks = await sql`
        INSERT INTO stock_positions (
          project_id, item_code, item_name, description, category, uom,
          available_quantity, on_hand_quantity, warehouse_location, bin_location,
          reorder_level, max_stock_level, average_unit_cost, total_value, stock_status, is_active
        )
        VALUES (
          ${newItem.projectId || projectId},
          ${newItem.itemCode || ''},
          ${newItem.name},
          ${newItem.description || ''},
          ${newItem.category || 'General'},
          ${newItem.unit},
          ${newItem.quantity || 0},
          ${newItem.quantity || 0},
          ${newItem.warehouse || 'Main Warehouse'},
          ${newItem.location || ''},
          ${newItem.minQuantity || 0},
          ${newItem.maxQuantity || 0},
          ${newItem.unitCost || 0},
          ${newItem.totalValue || 0},
          ${newItem.status || 'in_stock'},
          true
        )
        RETURNING *
      `;

      // Log stock item creation
      if (insertedStocks[0]) {
        logCreate('stock_item', insertedStocks[0]!.id, {
          project_id: insertedStocks[0]!.project_id,
          item_code: insertedStocks[0]!.item_code,
          item_name: insertedStocks[0]!.item_name,
          quantity: insertedStocks[0]!.quantity_on_hand,
          warehouse: insertedStocks[0]!.warehouse_location
        });
      }

      return apiResponse.created(res, {
        message: 'Stock item added successfully',
        item: insertedStocks[0]
      });
    } catch (error) {
      log.error('Error adding stock item', { error, module: 'procurement:stock' });
      return apiResponse.internalError(res, error);
    }
  } else {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
  }
}))

/**
 * Transfer Handler
 * Specialized handling for stock transfer errors
 */

import { StockTransferError } from '../../tracking';
import { RetryStrategy } from '../index';
import { MovementUtils } from './movement-utils';

/**
 * Handlers for stock transfer errors
 */
export class TransferHandler {
  /**
   * Handle stock transfer errors with routing and scheduling strategies
   */
  static handleTransferError(error: StockTransferError): {
    error: StockTransferError;
    retryStrategies: RetryStrategy[];
    severity: 'low' | 'medium' | 'high' | 'critical';
    autoRecoverable: boolean;
  } {
    const retryStrategies: RetryStrategy[] = [];

    // Direct transfer retry with validation
    retryStrategies.push({
      type: 'validated_direct_transfer',
      description: 'Retry direct transfer with enhanced validation',
      action: 'retry_direct_transfer',
      maxAttempts: 2,
      backoffMs: 5000,
      estimatedTime: '3-8 minutes',
      data: {
        itemCode: error.itemCode,
        fromLocation: error.fromLocation,
        toLocation: error.toLocation,
        quantity: error.quantity,
        validationChecks: {
          sourceAvailability: true,
          destinationCapacity: true,
          transferAuthorization: true,
          routeAccessibility: true
        }
      }
    });

    // Multi-hop transfer (via intermediate locations)
    const intermediateLocations = MovementUtils.findIntermediateLocations(error.fromLocation, error.toLocation);
    if (intermediateLocations.length > 0) {
      retryStrategies.push({
        type: 'multi_hop_transfer',
        description: `Route transfer via ${intermediateLocations[0]} for improved reliability`,
        action: 'initiate_multi_hop_transfer',
        maxAttempts: 1,
        estimatedTime: '30-90 minutes',
        data: {
          itemCode: error.itemCode,
          originalFromLocation: error.fromLocation,
          originalToLocation: error.toLocation,
          quantity: error.quantity,
          intermediateLocation: intermediateLocations[0],
          routingStrategy: 'reliable_path',
          consolidateAtIntermediate: error.quantity > 50
        }
      });
    }

    // Batch transfer for large quantities
    if (error.quantity > 20) {
      const batchSize = Math.min(error.quantity / 3, 25);
      const numberOfBatches = Math.ceil(error.quantity / batchSize);

      retryStrategies.push({
        type: 'batch_transfer',
        description: `Transfer in ${numberOfBatches} batches of ${Math.floor(batchSize)} units`,
        action: 'execute_batch_transfer',
        maxAttempts: 1,
        estimatedTime: `${numberOfBatches * 15}-${numberOfBatches * 30} minutes`,
        data: {
          itemCode: error.itemCode,
          fromLocation: error.fromLocation,
          toLocation: error.toLocation,
          totalQuantity: error.quantity,
          batchSize: Math.floor(batchSize),
          numberOfBatches,
          batchInterval: 300000, // 5 minutes between batches
          verifyEachBatch: true,
          rollbackOnBatchFailure: true
        }
      });
    }

    // Scheduled transfer during optimal conditions
    retryStrategies.push({
      type: 'scheduled_transfer',
      description: 'Schedule transfer during off-peak hours for better success rate',
      action: 'schedule_optimal_transfer',
      maxAttempts: 1,
      estimatedTime: 'Scheduled (within next 24 hours)',
      data: {
        itemCode: error.itemCode,
        fromLocation: error.fromLocation,
        toLocation: error.toLocation,
        quantity: error.quantity,
        schedulingPreferences: {
          preferredTimeSlots: ['02:00-06:00', '14:00-16:00'], // Low activity periods
          avoidMaintenanceWindows: true,
          considerLocationWorkHours: true,
          maxScheduleDelay: 24 * 60 * 60 * 1000 // 24 hours
        },
        priority: 'normal'
      }
    });

    // Emergency override transfer (for critical needs)
    retryStrategies.push({
      type: 'emergency_override',
      description: 'Execute transfer with emergency override (requires authorization)',
      action: 'request_emergency_override',
      maxAttempts: 1,
      estimatedTime: '10-60 minutes (requires approval)',
      data: {
        itemCode: error.itemCode,
        fromLocation: error.fromLocation,
        toLocation: error.toLocation,
        quantity: error.quantity,
        overrideReason: 'Critical business requirement',
        requiresApproval: true,
        approvalLevel: 'manager',
        businessJustification: this.generateBusinessJustification(error)
      }
    });

    const severity = this.determineTransferSeverity(error);
    const autoRecoverable = !error.reason.includes('authorization') && !error.reason.includes('capacity');

    return {
      error,
      retryStrategies,
      severity,
      autoRecoverable
    };
  }

  /**
   * Determine transfer error severity
   */
  private static determineTransferSeverity(error: StockTransferError): 'low' | 'medium' | 'high' | 'critical' {
    // Authorization issues are typically high severity
    if (error.reason.includes('authorization') || error.reason.includes('permission')) {
      return 'high';
    }

    // Capacity issues can be critical for large transfers
    if (error.reason.includes('capacity') && error.quantity > 100) {
      return 'critical';
    }

    // Large quantity transfers are generally higher priority
    if (error.quantity > 200) {
      return 'high';
    }

    return 'medium'; // Default for transfer errors
  }

  /**
   * Generate business justification for emergency override
   */
  private static generateBusinessJustification(error: StockTransferError): string {
    const reasons = [];

    if (error.quantity > 100) {
      reasons.push('Large quantity transfer required for operational continuity');
    }

    if (error.reason.includes('urgent')) {
      reasons.push('Urgent business requirement with time-sensitive deadline');
    }

    reasons.push(`Failed standard transfer processing: ${error.reason}`);
    reasons.push('Emergency override requested to prevent business disruption');

    return reasons.join('. ');
  }
}

/**
 * Odoo Stock Transfer Sync Service
 *
 * Syncs internal stock transfers (stock.picking with picking_type_code='internal')
 * from Odoo to FibreFlow stock_movements table
 *
 * Mapping:
 * - Odoo stock.picking (type=internal) → FF stock_movements (movement_type='transfer')
 * - Odoo stock.move → individual movement records
 */

import { neon, NeonQueryFunction } from '@/lib/db-neon';
import { createLogger } from '@/lib/logger';
import { OdooClient, OdooStockPicking, OdooStockMove } from '../odooClient';

const logger = createLogger('odooStockTransferSync');

// ============================================================================
// Types
// ============================================================================

export interface StockTransferSyncResult {
  created: number;
  updated: number;
  skipped: number;
  errors: string[];
  details: Array<{
    odooPickingId: number;
    odooPickingName: string;
    action: 'created' | 'updated' | 'skipped' | 'error';
    movementsCreated?: number;
    message?: string;
  }>;
}

export interface StockTransferSyncOptions {
  dryRun?: boolean;
  sinceDate?: Date;
  limit?: number;
  skipExisting?: boolean;
}

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Get stock item ID by Odoo product ID
 */
async function getStockItemByOdooId(
  sql: any,
  odooProductId: number
): Promise<string | null> {
  const rows = await sql`
    SELECT id FROM stock_items WHERE odoo_product_id = ${odooProductId} LIMIT 1
  `;
  return rows.length > 0 ? rows[0].id : null;
}

/**
 * Get FF location ID by Odoo location ID
 */
async function getLocationByOdooId(
  sql: any,
  odooLocationId: number
): Promise<string | null> {
  // First check odoo_location_mappings
  const mappingRows = await sql`
    SELECT ff_location_id FROM odoo_location_mappings
    WHERE odoo_location_id = ${odooLocationId}
    AND ff_location_id IS NOT NULL
    LIMIT 1
  `;
  if (mappingRows.length > 0) {
    return mappingRows[0].ff_location_id;
  }

  // Fallback: check stock_locations directly (if odoo_location_id column exists)
  try {
    const directRows = await sql`
      SELECT id FROM stock_locations
      WHERE odoo_location_id = ${odooLocationId}
      LIMIT 1
    `;
    return directRows.length > 0 ? directRows[0].id : null;
  } catch {
    return null;
  }
}

/**
 * Get default location (warehouse)
 */
async function getDefaultLocation(
  sql: any
): Promise<string | null> {
  const rows = await sql`
    SELECT id FROM stock_locations
    WHERE location_type = 'warehouse'
    ORDER BY name ASC
    LIMIT 1
  `;
  return rows.length > 0 ? rows[0].id : null;
}

/**
 * Check if a movement with this odoo_move_id exists
 */
async function getExistingMovement(
  sql: any,
  odooMoveId: number
): Promise<string | null> {
  const rows = await sql`
    SELECT id FROM stock_movements WHERE odoo_move_id = ${odooMoveId} LIMIT 1
  `;
  return rows.length > 0 ? rows[0].id : null;
}

// ============================================================================
// Main Sync Function
// ============================================================================

/**
 * Sync stock transfers from Odoo to FibreFlow
 */
export async function syncStockTransfers(
  client: OdooClient,
  databaseUrl: string,
  options: StockTransferSyncOptions = {}
): Promise<StockTransferSyncResult> {
  const sql = neon(databaseUrl);

  const result: StockTransferSyncResult = {
    created: 0,
    updated: 0,
    skipped: 0,
    errors: [],
    details: [],
  };

  const { dryRun = false, sinceDate, limit = 200, skipExisting = true } = options;

  try {
    logger.info('Starting stock transfer sync from Odoo', { dryRun, sinceDate, limit });

    // Get default location for fallback
    const defaultLocationId = await getDefaultLocation(sql);

    // Fetch completed internal transfers from Odoo
    const odooTransfers = await client.getCompletedTransfers({
      sinceDate,
      limit,
    } as any);

    logger.info(`Found ${odooTransfers.length} internal transfers in Odoo`);

    // Process each transfer
    for (const transfer of odooTransfers) {
      try {
        // Get stock moves for this picking
        const moves = await client.getStockMovesForPickings([transfer.id]);

        if (moves.length === 0) {
          result.skipped++;
          result.details.push({
            odooPickingId: transfer.id,
            odooPickingName: transfer.name,
            action: 'skipped',
            message: 'No stock moves found',
          });
          continue;
        }

        // Check if transfer already synced
        const existingMoves = await Promise.all(
          moves.map((m) => getExistingMovement(sql, m.id))
        );
        const allExist = existingMoves.every((e) => e !== null);

        if (allExist && skipExisting) {
          result.skipped++;
          result.details.push({
            odooPickingId: transfer.id,
            odooPickingName: transfer.name,
            action: 'skipped',
            message: 'All moves already synced',
          });
          continue;
        }

        // Dry run - log what would happen
        if (dryRun) {
          result.created++;
          result.details.push({
            odooPickingId: transfer.id,
            odooPickingName: transfer.name,
            action: 'created',
            movementsCreated: moves.length,
            message: `Dry run - would create ${moves.length} movements`,
          });
          continue;
        }

        // Get locations for this transfer
        const fromLocationId = transfer.location_id
          ? await getLocationByOdooId(sql, transfer.location_id[0])
          : defaultLocationId;
        const toLocationId = transfer.location_dest_id
          ? await getLocationByOdooId(sql, transfer.location_dest_id[0])
          : defaultLocationId;

        // Process each move
        let movementsCreated = 0;
        for (const move of moves) {
          try {
            // Skip if already exists
            const existingId = await getExistingMovement(sql, move.id);
            if (existingId && skipExisting) {
              continue;
            }

            // Get stock item
            const stockItemId = move.product_id
              ? await getStockItemByOdooId(sql, move.product_id[0])
              : null;

            if (!stockItemId) {
              logger.warn(`Stock item not found for product ${(move.product_id as any)?.[1] || 'unknown'}`);
              continue;
            }

            // Get move-specific locations (may differ from picking)
            const moveFromLocation = move.location_id
              ? (await getLocationByOdooId(sql, move.location_id[0])) || fromLocationId
              : fromLocationId;
            const moveToLocation = move.location_dest_id
              ? (await getLocationByOdooId(sql, move.location_dest_id[0])) || toLocationId
              : toLocationId;

            if (existingId) {
              // Update existing movement
              await sql`
                UPDATE stock_movements
                SET
                  quantity = ${move.quantity},
                  from_location_id = ${moveFromLocation},
                  to_location_id = ${moveToLocation},
                  performed_at = ${move.date ? new Date(move.date) : new Date()},
                  odoo_synced_at = NOW()
                WHERE id = ${existingId}
              `;
              result.updated++;
            } else {
              // Create new movement
              await sql`
                INSERT INTO stock_movements (
                  stock_item_id,
                  movement_type,
                  from_location_id,
                  to_location_id,
                  quantity,
                  reference,
                  notes,
                  performed_by,
                  performed_at,
                  odoo_move_id,
                  odoo_picking_id,
                  source_type,
                  odoo_synced_at
                ) VALUES (
                  ${stockItemId},
                  'transfer',
                  ${moveFromLocation},
                  ${moveToLocation},
                  ${move.quantity},
                  ${transfer.name},
                  ${'Odoo internal transfer: ' + (move.reference || transfer.name)},
                  'odoo-sync',
                  ${move.date ? new Date(move.date) : new Date()},
                  ${move.id},
                  ${transfer.id},
                  'odoo_transfer',
                  NOW()
                )
              `;
              movementsCreated++;
            }
          } catch (moveError) {
            const msg = moveError instanceof Error ? moveError.message : 'Unknown error';
            logger.warn(`Error syncing move ${move.id}`, { error: msg });
          }
        }

        result.created++;
        result.details.push({
          odooPickingId: transfer.id,
          odooPickingName: transfer.name,
          action: movementsCreated > 0 ? 'created' : 'updated',
          movementsCreated,
        });
      } catch (transferError) {
        const message = transferError instanceof Error ? transferError.message : 'Unknown error';
        result.errors.push(`${transfer.name}: ${message}`);
        result.details.push({
          odooPickingId: transfer.id,
          odooPickingName: transfer.name,
          action: 'error',
          message,
        });
        logger.error(`Error syncing transfer ${transfer.name}`, { error: message });
      }
    }

    // Record sync timestamp
    if (!dryRun) {
      try {
        await sql`
          UPDATE odoo_api_config
          SET last_sync_stock_transfers = NOW()
          WHERE id = (SELECT id FROM odoo_api_config LIMIT 1)
        `;
      } catch {
        logger.debug('Could not update last_sync_stock_transfers');
      }

      try {
        await sql`
          INSERT INTO odoo_sync_history (
            entity_type, sync_type, records_processed, records_created,
            records_updated, records_failed, status, error_details, completed_at
          ) VALUES (
            'stock_transfer', 'full', ${odooTransfers.length}, ${result.created},
            ${result.updated}, ${result.errors.length},
            ${result.errors.length > 0 ? 'completed_with_errors' : 'completed'},
            ${result.errors.length > 0 ? JSON.stringify(result.errors) : null},
            CURRENT_TIMESTAMP
          )
        `;
      } catch {
        logger.debug('Could not record sync history');
      }
    }

    logger.info('Stock transfer sync completed', {
      created: result.created,
      updated: result.updated,
      skipped: result.skipped,
      errors: result.errors.length,
    });

    return result;
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    logger.error('Stock transfer sync failed', { error: message });
    result.errors.push(`Sync failed: ${message}`);
    return result;
  }
}

/**
 * Get stock transfer sync statistics
 */
export async function getStockTransferSyncStats(
  databaseUrl: string
): Promise<{
  totalMovements: number;
  odooSynced: number;
  byType: Array<{ type: string; count: number }>;
  lastSync: Date | null;
}> {
  const sql = neon(databaseUrl);

  const [totals, byType, lastSync] = await Promise.all([
    sql`
      SELECT
        COUNT(*) as total,
        COUNT(*) FILTER (WHERE odoo_move_id IS NOT NULL) as odoo_synced
      FROM stock_movements
    `,
    sql`
      SELECT movement_type, COUNT(*) as count
      FROM stock_movements
      GROUP BY movement_type
      ORDER BY count DESC
    `,
    sql`
      SELECT last_sync_stock_transfers as last_sync
      FROM odoo_api_config
      LIMIT 1
    `,
  ]);

  const stats = totals[0] || { total: '0', odoo_synced: '0' };

  return {
    totalMovements: parseInt(stats.total, 10),
    odooSynced: parseInt(stats.odoo_synced, 10),
    byType: byType.map((t) => ({
      type: t.movement_type,
      count: parseInt(t.count, 10),
    })),
    lastSync: lastSync[0]?.last_sync || null,
  };
}

/**
 * Stock Management Module - Main Tab Component
 * Comprehensive inventory management with dashboard, operations, and warehouse management
 */

import React, { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import {
  Package,
  TrendingUp,
  AlertTriangle,
  BarChart3,
  Truck,
  Scan,
  Search,
  Filter,
  ArrowRight,
  ArrowLeft,
  Plus,
  RefreshCw,
  Eye,
  Tag,
  MapPin,
  Calendar,
  User,
  FileText,
  CheckCircle,
  XCircle
} from 'lucide-react';
import { Button } from '@/shared/components/ui/Button';
import { log } from '@/lib/logger';
import { formatDisplayDate } from '@/utils/dateFormat';

// Types
interface StockItemDisplay {
  id: string;
  itemCode: string;
  name: string;
  description: string;
  category: string;
  unit: string;
  quantity: number;
  minQuantity: number;
  maxQuantity: number;
  unitCost: number;
  totalValue: number;
  warehouse: string;
  location: string;
  supplier: string;
  lastRestocked: string;
  status: 'in_stock' | 'low_stock' | 'out_of_stock';
}

interface StockMovementDisplay {
  id: string;
  type: 'GRN' | 'ISSUE' | 'TRANSFER' | 'ADJUSTMENT';
  reference_number: string;
  item_code?: string;
  item_name?: string;
  quantity?: number;
  uom?: string;
  from_location?: string;
  to_location?: string;
  movement_date: string;
  status: string;
  requested_by?: string;
  notes?: string;
}

interface StockMetrics {
  totalItems: number;
  totalValue: number;
  lowStockItems: number;
  outOfStockItems: number;
  pendingReceipts: number;
  pendingIssues: number;
  stockTurnover: number;
  warehouseUtilization: number;
}

interface StockManagementProps {
  projectId?: string;
  projectName?: string;
}

type FilterStatus = 'all' | 'in_stock' | 'low_stock' | 'out_of_stock';
type SortBy = 'name' | 'itemCode' | 'quantity' | 'value' | 'lastRestocked';
type ActiveTab = 'inventory' | 'movements';

export default function StockManagement({ projectId, projectName }: StockManagementProps) {
  const router = useRouter();

  // State
  const [activeTab, setActiveTab] = useState<ActiveTab>('inventory');
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [items, setItems] = useState<StockItemDisplay[]>([]);
  const [movements, setMovements] = useState<StockMovementDisplay[]>([]);
  const [metrics, setMetrics] = useState<StockMetrics>({
    totalItems: 0,
    totalValue: 0,
    lowStockItems: 0,
    outOfStockItems: 0,
    pendingReceipts: 0,
    pendingIssues: 0,
    stockTurnover: 0,
    warehouseUtilization: 0
  });

  // Filter/Search state
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState<FilterStatus>('all');
  const [sortBy, setSortBy] = useState<SortBy>('name');
  const [selectedItems, setSelectedItems] = useState<Set<string>>(new Set());

  // Load stock data from API
  const loadData = useCallback(async () => {
    try {
      setIsLoading(true);
      setError(null);

      const url = projectId && projectId !== 'all'
        ? `/api/procurement/stock?projectId=${projectId}`
        : '/api/procurement/stock';

      const response = await fetch(url);
      if (!response.ok) {
        throw new Error('Failed to fetch stock data');
      }
      const data = await response.json();

      // Transform items to display format
      const stockItems: StockItemDisplay[] = (data.items || []).map((item: any) => ({
        id: item.id,
        itemCode: item.itemCode || 'N/A',
        name: item.name || item.itemName || 'Unnamed Item',
        description: item.description || '',
        category: item.category || 'General',
        unit: item.unit || 'EA',
        quantity: Number(item.quantity || 0),
        minQuantity: Number(item.minQuantity || 0),
        maxQuantity: Number(item.maxQuantity || 0),
        unitCost: Number(item.unitCost || 0),
        totalValue: Number(item.totalValue || 0),
        warehouse: item.warehouse || 'Main Warehouse',
        location: item.location || '',
        supplier: item.supplier || 'Unknown',
        lastRestocked: item.lastRestocked || '',
        status: item.status || determineStatus(item)
      }));

      setItems(stockItems);
      setMovements(data.movements || []);

      // Calculate metrics
      const lowStock = stockItems.filter(item => item.status === 'low_stock').length;
      const outOfStock = stockItems.filter(item => item.status === 'out_of_stock').length;
      const totalValue = stockItems.reduce((sum, item) => sum + (item.totalValue || 0), 0);

      setMetrics({
        totalItems: stockItems.length,
        totalValue,
        lowStockItems: lowStock,
        outOfStockItems: outOfStock,
        pendingReceipts: 0,
        pendingIssues: 0,
        stockTurnover: 0,
        warehouseUtilization: 0
      });

    } catch (err) {
      log.error('Failed to load stock data:', { data: err }, 'StockManagement');
      setError('Failed to load stock data. Please try again.');
    } finally {
      setIsLoading(false);
    }
  }, [projectId]);

  // Helper to determine status from quantity
  function determineStatus(item: any): 'in_stock' | 'low_stock' | 'out_of_stock' {
    const qty = Number(item.quantity || 0);
    const minQty = Number(item.minQuantity || item.reorderLevel || 10);
    if (qty <= 0) return 'out_of_stock';
    if (qty <= minQty) return 'low_stock';
    return 'in_stock';
  }

  useEffect(() => {
    loadData();
  }, [loadData]);

  // Listen for refresh events
  useEffect(() => {
    const handleRefresh = () => loadData();
    window.addEventListener('stockDataRefresh', handleRefresh);
    return () => window.removeEventListener('stockDataRefresh', handleRefresh);
  }, [loadData]);

  // Filter and sort items
  const filteredItems = items
    .filter(item => {
      // Search filter
      if (searchTerm) {
        const search = searchTerm.toLowerCase();
        const matchesSearch =
          item.name.toLowerCase().includes(search) ||
          item.itemCode.toLowerCase().includes(search) ||
          item.category.toLowerCase().includes(search) ||
          item.description.toLowerCase().includes(search);
        if (!matchesSearch) return false;
      }

      // Status filter
      if (filterStatus !== 'all' && item.status !== filterStatus) {
        return false;
      }

      return true;
    })
    .sort((a, b) => {
      switch (sortBy) {
        case 'itemCode':
          return a.itemCode.localeCompare(b.itemCode);
        case 'quantity':
          return b.quantity - a.quantity;
        case 'value':
          return b.totalValue - a.totalValue;
        case 'lastRestocked':
          return new Date(b.lastRestocked).getTime() - new Date(a.lastRestocked).getTime();
        case 'name':
        default:
          return a.name.localeCompare(b.name);
      }
    });

  // Handle item selection
  const toggleItemSelect = (id: string) => {
    const newSelected = new Set(selectedItems);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedItems(newSelected);
  };

  const selectAll = () => {
    if (selectedItems.size === filteredItems.length) {
      setSelectedItems(new Set());
    } else {
      setSelectedItems(new Set(filteredItems.map(item => item.id)));
    }
  };

  // Status badge component
  const StatusBadge = ({ status }: { status: StockItemDisplay['status'] }) => {
    const config = {
      'in_stock': { bg: 'bg-green-500/20', text: 'text-green-400', icon: CheckCircle, label: 'In Stock' },
      'low_stock': { bg: 'bg-yellow-500/20', text: 'text-yellow-400', icon: AlertTriangle, label: 'Low Stock' },
      'out_of_stock': { bg: 'bg-red-500/20', text: 'text-red-400', icon: XCircle, label: 'Out of Stock' }
    };
    const { bg, text, icon: Icon, label } = config[status] || config['in_stock'];
    return (
      <span className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium ${bg} ${text}`}>
        <Icon className="h-3 w-3" />
        {label}
      </span>
    );
  };

  // Movement type badge
  const MovementTypeBadge = ({ type }: { type: string }) => {
    const config: Record<string, { bg: string; text: string; icon: React.ElementType; label: string }> = {
      'GRN': { bg: 'bg-green-500/20', text: 'text-green-400', icon: Package, label: 'Receipt' },
      'ISSUE': { bg: 'bg-purple-500/20', text: 'text-purple-400', icon: ArrowRight, label: 'Issue' },
      'TRANSFER': { bg: 'bg-orange-500/20', text: 'text-orange-400', icon: ArrowLeft, label: 'Transfer' },
      'ADJUSTMENT': { bg: 'bg-blue-500/20', text: 'text-blue-400', icon: FileText, label: 'Adjustment' }
    };
    const defaultConfig = { bg: 'bg-green-500/20', text: 'text-green-400', icon: Package, label: 'Receipt' };
    const { bg, text, icon: Icon, label } = config[type] ?? defaultConfig;
    return (
      <span className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium ${bg} ${text}`}>
        <Icon className="h-3 w-3" />
        {label}
      </span>
    );
  };

  // Format date helper — delegates to centralized utility
  const formatDate = (dateStr: string) => formatDisplayDate(dateStr);

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Stock Management</h1>
          {projectName && (
            <p className="text-sm text-[var(--ff-text-secondary)] mt-1">
              Comprehensive inventory control for {projectName}
            </p>
          )}
        </div>

        <div className="flex items-center gap-3">
          <Button
            variant="outline"
            onClick={() => {/* TODO: Barcode scanning */}}
            className="hidden sm:flex"
          >
            <Scan className="h-4 w-4 mr-2" />
            Scan Barcode
          </Button>

          <Button
            variant="outline"
            onClick={() => router.push('/procurement/inventory?tab=reports')}
          >
            <BarChart3 className="h-4 w-4 mr-2" />
            Reports
          </Button>

          <Button
            variant="outline"
            onClick={loadData}
            disabled={isLoading}
          >
            <RefreshCw className={`h-4 w-4 mr-2 ${isLoading ? 'animate-spin' : ''}`} />
            Refresh
          </Button>
        </div>
      </div>

      {/* Critical Alerts */}
      {(metrics.lowStockItems > 0 || metrics.outOfStockItems > 0) && (
        <div className="bg-red-500/10 border border-red-500/30 rounded-lg p-4">
          <div className="flex items-start gap-3">
            <AlertTriangle className="h-5 w-5 text-red-400 mt-0.5" />
            <div className="flex-1">
              <h3 className="font-medium text-red-400">Stock Level Alerts</h3>
              <p className="text-sm text-red-300 mt-1">
                {metrics.outOfStockItems > 0 &&
                  `${metrics.outOfStockItems} item${metrics.outOfStockItems !== 1 ? 's' : ''} out of stock. `
                }
                {metrics.lowStockItems > 0 &&
                  `${metrics.lowStockItems} item${metrics.lowStockItems !== 1 ? 's' : ''} below minimum level. `
                }
                Immediate action required to prevent project delays.
              </p>
            </div>
            <Button
              size="sm"
              onClick={() => setFilterStatus('low_stock')}
              className="bg-red-600 text-white hover:bg-red-700"
            >
              View Low Stock
            </Button>
          </div>
        </div>
      )}

      {/* Key Metrics Overview */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
          <div className="flex items-center">
            <div className="p-2 bg-blue-500/20 rounded-lg">
              <Package className="h-5 w-5 text-blue-400" />
            </div>
            <div className="ml-3">
              <p className="text-sm text-[var(--ff-text-secondary)]">Total Items</p>
              <p className="text-xl font-bold text-[var(--ff-text-primary)]">{metrics.totalItems.toLocaleString()}</p>
            </div>
          </div>
        </div>

        <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
          <div className="flex items-center">
            <div className="p-2 bg-green-500/20 rounded-lg">
              <TrendingUp className="h-5 w-5 text-green-400" />
            </div>
            <div className="ml-3">
              <p className="text-sm text-[var(--ff-text-secondary)]">Total Value</p>
              <p className="text-xl font-bold text-green-400">
                R {(metrics.totalValue / 1000).toFixed(0)}k
              </p>
            </div>
          </div>
        </div>

        <div
          className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4 cursor-pointer hover:border-yellow-500/50 transition-colors"
          onClick={() => setFilterStatus('low_stock')}
        >
          <div className="flex items-center">
            <div className="p-2 bg-yellow-500/20 rounded-lg">
              <AlertTriangle className="h-5 w-5 text-yellow-400" />
            </div>
            <div className="ml-3">
              <p className="text-sm text-[var(--ff-text-secondary)]">Low Stock</p>
              <p className="text-xl font-bold text-yellow-400">{metrics.lowStockItems}</p>
            </div>
          </div>
        </div>

        <div
          className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4 cursor-pointer hover:border-red-500/50 transition-colors"
          onClick={() => setFilterStatus('out_of_stock')}
        >
          <div className="flex items-center">
            <div className="p-2 bg-red-500/20 rounded-lg">
              <XCircle className="h-5 w-5 text-red-400" />
            </div>
            <div className="ml-3">
              <p className="text-sm text-[var(--ff-text-secondary)]">Out of Stock</p>
              <p className="text-xl font-bold text-red-400">{metrics.outOfStockItems}</p>
            </div>
          </div>
        </div>
      </div>

      {/* Tab Navigation */}
      <div className="flex gap-2 border-b border-[var(--ff-border-light)]">
        <button
          onClick={() => setActiveTab('inventory')}
          className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
            activeTab === 'inventory'
              ? 'border-[var(--ff-primary-500)] text-[var(--ff-primary-400)]'
              : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'
          }`}
        >
          <Package className="h-4 w-4 inline-block mr-2" />
          Inventory ({filteredItems.length})
        </button>
        <button
          onClick={() => setActiveTab('movements')}
          className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
            activeTab === 'movements'
              ? 'border-[var(--ff-primary-500)] text-[var(--ff-primary-400)]'
              : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'
          }`}
        >
          <Truck className="h-4 w-4 inline-block mr-2" />
          Movements ({movements.length})
        </button>
      </div>

      {/* Loading State */}
      {isLoading && (
        <div className="flex items-center justify-center py-12">
          <RefreshCw className="h-8 w-8 animate-spin text-[var(--ff-primary-500)]" />
        </div>
      )}

      {/* Error State */}
      {error && !isLoading && (
        <div className="bg-red-500/10 border border-red-500/30 rounded-lg p-4 text-center">
          <p className="text-red-400">{error}</p>
          <Button variant="outline" onClick={loadData} className="mt-2">
            Try Again
          </Button>
        </div>
      )}

      {/* Inventory Tab */}
      {!isLoading && !error && activeTab === 'inventory' && (
        <div className="space-y-4">
          {/* Filters */}
          <div className="flex flex-col sm:flex-row gap-4 items-start sm:items-center justify-between">
            <div className="flex flex-wrap gap-3">
              <div className="flex items-center gap-2">
                <Search className="h-4 w-4 text-[var(--ff-text-tertiary)]" />
                <input
                  type="text"
                  placeholder="Search items..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-md px-3 py-1.5 text-sm text-[var(--ff-text-primary)] placeholder:text-[var(--ff-text-tertiary)] w-64 focus:outline-none focus:border-[var(--ff-primary-500)]"
                />
              </div>
              <div className="flex items-center gap-2">
                <Filter className="h-4 w-4 text-[var(--ff-text-tertiary)]" />
                <select
                  value={filterStatus}
                  onChange={(e) => setFilterStatus(e.target.value as FilterStatus)}
                  className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-md px-3 py-1.5 text-sm text-[var(--ff-text-primary)]"
                >
                  <option value="all">All Status</option>
                  <option value="in_stock">In Stock</option>
                  <option value="low_stock">Low Stock</option>
                  <option value="out_of_stock">Out of Stock</option>
                </select>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-sm text-[var(--ff-text-tertiary)]">Sort:</span>
                <select
                  value={sortBy}
                  onChange={(e) => setSortBy(e.target.value as SortBy)}
                  className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-md px-3 py-1.5 text-sm text-[var(--ff-text-primary)]"
                >
                  <option value="name">Name</option>
                  <option value="itemCode">Item Code</option>
                  <option value="quantity">Quantity</option>
                  <option value="value">Value</option>
                  <option value="lastRestocked">Last Restocked</option>
                </select>
              </div>
            </div>

            {selectedItems.size > 0 && (
              <div className="flex items-center gap-2">
                <span className="text-sm text-[var(--ff-text-secondary)]">{selectedItems.size} selected</span>
                <Button variant="outline" size="sm">
                  <ArrowRight className="h-4 w-4 mr-1" />
                  Issue
                </Button>
                <Button variant="outline" size="sm">
                  <ArrowLeft className="h-4 w-4 mr-1" />
                  Transfer
                </Button>
              </div>
            )}
          </div>

          {/* Stock Items List */}
          {filteredItems.length === 0 ? (
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-12 text-center">
              <Package className="mx-auto h-12 w-12 text-[var(--ff-text-tertiary)]" />
              <h3 className="mt-4 text-lg font-medium text-[var(--ff-text-primary)]">No Stock Items Found</h3>
              <p className="mt-2 text-[var(--ff-text-secondary)]">
                {searchTerm || filterStatus !== 'all'
                  ? 'Try adjusting your search or filter criteria.'
                  : 'No stock items have been added yet.'}
              </p>
              {filterStatus !== 'all' && (
                <Button variant="outline" onClick={() => setFilterStatus('all')} className="mt-4">
                  Clear Filters
                </Button>
              )}
            </div>
          ) : (
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
              {/* Header */}
              <div className="p-4 border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                <div className="flex items-center gap-4">
                  <input
                    type="checkbox"
                    checked={selectedItems.size === filteredItems.length && filteredItems.length > 0}
                    onChange={selectAll}
                    className="h-4 w-4 rounded border-[var(--ff-border-light)]"
                  />
                  <span className="text-sm font-medium text-[var(--ff-text-secondary)]">
                    {filteredItems.length} item{filteredItems.length !== 1 ? 's' : ''}
                  </span>
                </div>
              </div>

              {/* Items */}
              <div className="divide-y divide-[var(--ff-border-light)]">
                {filteredItems.map((item) => (
                  <div
                    key={item.id}
                    className="p-4 hover:bg-[var(--ff-bg-hover)] transition-colors"
                  >
                    <div className="flex items-start gap-4">
                      <input
                        type="checkbox"
                        checked={selectedItems.has(item.id)}
                        onChange={() => toggleItemSelect(item.id)}
                        className="mt-1 h-4 w-4 rounded border-[var(--ff-border-light)]"
                      />

                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-3 mb-2">
                          <h3 className="font-semibold text-[var(--ff-text-primary)]">{item.name}</h3>
                          <span className="text-sm text-[var(--ff-text-tertiary)]">{item.itemCode}</span>
                          <StatusBadge status={item.status} />
                        </div>

                        {item.description && (
                          <p className="text-sm text-[var(--ff-text-secondary)] mb-2">{item.description}</p>
                        )}

                        <div className="flex flex-wrap items-center gap-4 text-sm text-[var(--ff-text-tertiary)]">
                          <span className="flex items-center gap-1">
                            <Tag className="h-4 w-4" />
                            {item.category}
                          </span>
                          <span className="flex items-center gap-1">
                            <MapPin className="h-4 w-4" />
                            {item.warehouse}
                          </span>
                          {item.supplier && item.supplier !== 'Unknown' && (
                            <span className="flex items-center gap-1">
                              <Truck className="h-4 w-4" />
                              {item.supplier}
                            </span>
                          )}
                        </div>
                      </div>

                      {/* Quantities */}
                      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 text-right">
                        <div>
                          <p className="text-xs text-[var(--ff-text-tertiary)]">Current</p>
                          <p className={`font-semibold ${
                            item.status === 'out_of_stock' ? 'text-red-400' :
                            item.status === 'low_stock' ? 'text-yellow-400' :
                            'text-[var(--ff-text-primary)]'
                          }`}>
                            {item.quantity.toLocaleString()} {item.unit}
                          </p>
                        </div>
                        <div>
                          <p className="text-xs text-[var(--ff-text-tertiary)]">Min</p>
                          <p className="font-semibold text-[var(--ff-text-secondary)]">
                            {item.minQuantity.toLocaleString()} {item.unit}
                          </p>
                        </div>
                        <div>
                          <p className="text-xs text-[var(--ff-text-tertiary)]">Value</p>
                          <p className="font-semibold text-green-400">
                            R {item.totalValue.toLocaleString()}
                          </p>
                        </div>
                      </div>

                      {/* Actions */}
                      <div className="flex gap-2">
                        <Button variant="outline" size="sm">
                          <Eye className="h-4 w-4" />
                        </Button>
                        <Button variant="outline" size="sm">
                          <Plus className="h-4 w-4" />
                        </Button>
                        <Button variant="outline" size="sm">
                          <ArrowRight className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>

                    {/* Stock Level Bar */}
                    <div className="mt-3 ml-8">
                      <div className="flex items-center gap-2">
                        <div className="flex-1 h-2 bg-[var(--ff-bg-tertiary)] rounded-full overflow-hidden">
                          {item.maxQuantity > 0 ? (
                            <div
                              className={`h-full rounded-full ${
                                item.status === 'out_of_stock' ? 'bg-red-500' :
                                item.status === 'low_stock' ? 'bg-yellow-500' :
                                'bg-green-500'
                              }`}
                              style={{
                                width: `${Math.min(100, (item.quantity / item.maxQuantity) * 100)}%`
                              }}
                            />
                          ) : (
                            <div
                              className={`h-full rounded-full ${
                                item.quantity > 0 ? 'bg-green-500' : 'bg-red-500'
                              }`}
                              style={{ width: item.quantity > 0 ? '50%' : '0%' }}
                            />
                          )}
                        </div>
                        <span className="text-xs text-[var(--ff-text-tertiary)] w-16 text-right">
                          {item.maxQuantity > 0
                            ? `${Math.round((item.quantity / item.maxQuantity) * 100)}%`
                            : item.quantity > 0 ? 'OK' : 'Empty'}
                        </span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {/* Movements Tab */}
      {!isLoading && !error && activeTab === 'movements' && (
        <div className="space-y-4">
          {movements.length === 0 ? (
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-12 text-center">
              <Truck className="mx-auto h-12 w-12 text-[var(--ff-text-tertiary)]" />
              <h3 className="mt-4 text-lg font-medium text-[var(--ff-text-primary)]">No Stock Movements</h3>
              <p className="mt-2 text-[var(--ff-text-secondary)]">
                No stock movements have been recorded yet.
              </p>
            </div>
          ) : (
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
              <div className="divide-y divide-[var(--ff-border-light)]">
                {movements.map((movement) => (
                  <div
                    key={movement.id}
                    className="p-4 hover:bg-[var(--ff-bg-hover)] transition-colors"
                  >
                    <div className="flex items-start justify-between">
