interface PickingLine {
  id: string;
  stock_item_id: string;
  planned_quantity: number;
  serial_ids?: string[];
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { pickingId } = req.query;

  if (typeof pickingId !== 'string') {
    return apiResponse.validationError(res, { pickingId: 'Picking ID is required' });
  }

  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    // Get picking with lines
    const existing = await sql`
      SELECT
        p.*,
        json_agg(
          json_build_object(
            'id', pl.id,
            'stock_item_id', pl.stock_item_id,
            'planned_quantity', pl.planned_quantity,
            'serial_ids', pl.serial_ids
          )
        ) as lines
      FROM stock_pickings p
      LEFT JOIN stock_picking_lines pl ON pl.picking_id = p.id
      WHERE p.id = ${pickingId}
      GROUP BY p.id
    `;

    const picking = existing[0];
    if (!picking) {
      return apiResponse.notFound(res, 'Picking', pickingId);
    }

    if (picking.status !== 'confirmed') {
      return apiResponse.validationError(res, {
        status: `Cannot process picking with status "${picking.status}". Only confirmed pickings can be processed.`
      });
    }

    const sourceLocationId = picking.source_location_id as string;
    const destinationLocationId = picking.destination_location_id as string;
    const pickingType = picking.picking_type as string;

    // Update status to processing first
    await sql`
      UPDATE stock_pickings
      SET status = 'processing', updated_at = NOW()
      WHERE id = ${pickingId}
    `;

    // Process each line - update stock quants and serials
    const lines: PickingLine[] = (picking.lines as PickingLine[]) || [];
    for (const line of lines) {
      if (!line || !line.stock_item_id) continue;

      // Decrease source quant
      await sql`
        UPDATE stock_quants
        SET
          quantity = quantity - ${line.planned_quantity},
          last_movement_date = NOW(),
          updated_at = NOW()
        WHERE stock_item_id = ${line.stock_item_id}
          AND location_id = ${sourceLocationId}
      `;

      // Increase or create destination quant
      await sql`
        INSERT INTO stock_quants (stock_item_id, location_id, quantity, last_movement_date)
        VALUES (${line.stock_item_id}, ${destinationLocationId}, ${line.planned_quantity}, NOW())
        ON CONFLICT (stock_item_id, location_id, lot_number)
        DO UPDATE SET
          quantity = stock_quants.quantity + ${line.planned_quantity},
          last_movement_date = NOW(),
          updated_at = NOW()
      `;

      // Update serials if applicable
      if (line.serial_ids && Array.isArray(line.serial_ids)) {
        for (const serialId of line.serial_ids) {
          const newStatus = pickingType === 'issue' ? 'issued' : 'available';
          await sql`
            UPDATE stock_serials
            SET
              current_location_id = ${destinationLocationId},
              status = ${newStatus},
              updated_at = NOW()
            WHERE id = ${serialId}
          `;
        }
      }

      // Record movement
      await sql`
        INSERT INTO stock_movements (
          picking_id,
          stock_item_id,
          movement_type,
          from_location_id,
          to_location_id,
          quantity,
          performed_at
        ) VALUES (
          ${pickingId},
          ${line.stock_item_id},
          ${pickingType},
          ${sourceLocationId},
          ${destinationLocationId},
          ${line.planned_quantity},
          NOW()
        )
      `;

      // Update line status
      await sql`
        UPDATE stock_picking_lines
        SET
          status = 'done',
          actual_quantity = planned_quantity
        WHERE id = ${line.id}
      `;
    }

    // Update picking to done
    const result = await sql`
      UPDATE stock_pickings
      SET
        status = 'done',
        effective_date = NOW(),
        updated_at = NOW()
      WHERE id = ${pickingId}
      RETURNING *
    `;

    log.info('Picking processed', { pickingId, linesProcessed: lines.length }, 'field-stock');

    createAuditLog({
      entityType: 'picking',
      entityId: pickingId,
      action: 'update',
      performedBy: 'system',
      newValues: { status: 'done', linesProcessed: lines.length },
    });

    return apiResponse.success(res, result[0]);
  } catch (error: unknown) {
    log.error('[pickingId]-process', { error: error instanceof Error ? error.message : String(error) });
    // Rollback status on error
    await sql`
      UPDATE stock_pickings
      SET status = 'confirmed', updated_at = NOW()
      WHERE id = ${pickingId}
    `.catch((e) => log.warn('DB operation failed (non-critical)', { error: e instanceof Error ? e.message : 'unknown' }, 'field-stock'));

    log.error('Error processing picking', { error, pickingId }, 'field-stock');
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

/**
 * Confirm Picking API
 * POST /api/procurement/field-stock/pickings/[pickingId]/confirm
 * Transition picking from draft to confirmed status
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth } from '@/lib/auth';
import { createAuditLog } from '@/services/procurement/auditService';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { pickingId } = req.query;

  if (typeof pickingId !== 'string') {
    return apiResponse.validationError(res, { pickingId: 'Picking ID is required' });
  }

  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    // Check current status
    const existing = await sql`
      SELECT id, status FROM stock_pickings WHERE id = ${pickingId}
    `;

    const pickingRecord = existing[0];
    if (!pickingRecord) {
      return apiResponse.notFound(res, 'Picking', pickingId);
    }

    if (pickingRecord.status !== 'draft') {
      return apiResponse.validationError(res, {
        status: `Cannot confirm picking with status "${pickingRecord.status}". Only draft pickings can be confirmed.`
      });
    }

    // Update status to confirmed
    const result = await sql`
      UPDATE stock_pickings
      SET
        status = 'confirmed',
        updated_at = NOW()
      WHERE id = ${pickingId}
      RETURNING *
    `;

    log.info('Picking confirmed', { pickingId }, 'field-stock');

    createAuditLog({
      entityType: 'picking',
      entityId: pickingId,
      action: 'update',
      performedBy: 'system',
      newValues: { status: 'confirmed' },
    });

    return apiResponse.success(res, result[0]);
  } catch (error: unknown) {
    log.error('Error confirming picking', { error, pickingId }, 'field-stock');
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

/**
 * Stock Movement and Tracking Errors
 * Errors related to stock movements, transfers, and tracking operations
 */

import { StockError } from './inventory';
import type { 
  MovementType, 
  AdjustmentType, 
  MovementOptions, 
  TransferOptions, 
  AdjustmentOptions,
  TrackingOptions 
} from './types';

/**
 * Stock movement error for tracking issues
 */
export class StockMovementError extends StockError {
  public readonly movementType: MovementType;
  public readonly fromLocation?: string;
  public readonly toLocation?: string;
  public readonly itemCode: string;
  public readonly quantity: number;
  public readonly movementId?: string;

  constructor(
    message: string,
    movementType: MovementType,
    itemCode: string,
    quantity: number,
    options?: MovementOptions,
    context?: Record<string, any>
  ) {
    super(message, 'STOCK_MOVEMENT_FAILED', 400, context);
    this.name = 'StockMovementError';
    this.movementType = movementType;
    this.itemCode = itemCode;
    this.quantity = quantity;
    if (options?.fromLocation !== undefined) this.fromLocation = options.fromLocation;
    if (options?.toLocation !== undefined) this.toLocation = options.toLocation;
    if (options?.movementId !== undefined) this.movementId = options.movementId;
    Object.setPrototypeOf(this, StockMovementError.prototype);
  }

  override toJSON() {
    return {
      ...super.toJSON(),
      movementType: this.movementType,
      itemCode: this.itemCode,
      quantity: this.quantity,
      fromLocation: this.fromLocation,
      toLocation: this.toLocation,
      movementId: this.movementId
    };
  }

  /**
   * Get movement description
   */
  getMovementDescription(): string {
    switch (this.movementType) {
      case 'inbound':
        return `Receiving ${this.quantity} units of ${this.itemCode}${this.toLocation ? ` to ${this.toLocation}` : ''}`;
      case 'outbound':
        return `Issuing ${this.quantity} units of ${this.itemCode}${this.fromLocation ? ` from ${this.fromLocation}` : ''}`;
      case 'transfer':
        return `Transferring ${this.quantity} units of ${this.itemCode} from ${this.fromLocation} to ${this.toLocation}`;
      case 'adjustment':
        return `Adjusting ${this.quantity} units of ${this.itemCode}${this.fromLocation ? ` at ${this.fromLocation}` : ''}`;
      default:
        return `Stock movement of ${this.quantity} units of ${this.itemCode}`;
    }
  }
}

/**
 * Stock transfer error for location-to-location movement issues
 */
export class StockTransferError extends StockError {
  public readonly itemCode: string;
  public readonly fromLocation: string;
  public readonly toLocation: string;
  public readonly quantity: number;
  public readonly transferId?: string;
  public readonly reason: string;

  constructor(
    itemCode: string,
    fromLocation: string,
    toLocation: string,
    quantity: number,
    reason: string,
    options?: TransferOptions,
    context?: Record<string, any>
  ) {
    const message = `Stock transfer failed: ${reason}`;
    super(message, 'STOCK_TRANSFER_FAILED', 400, context);
    this.name = 'StockTransferError';
    this.itemCode = itemCode;
    this.fromLocation = fromLocation;
    this.toLocation = toLocation;
    this.quantity = quantity;
    this.reason = reason;
    if (options?.transferId !== undefined) this.transferId = options.transferId;
    Object.setPrototypeOf(this, StockTransferError.prototype);
  }

  override toJSON() {
    return {
      ...super.toJSON(),
      itemCode: this.itemCode,
      fromLocation: this.fromLocation,
      toLocation: this.toLocation,
      quantity: this.quantity,
      reason: this.reason,
      transferId: this.transferId,
      transferDescription: this.getTransferDescription()
    };
  }

  /**
   * Get transfer description
   */
  getTransferDescription(): string {
    return `Transfer ${this.quantity} units of ${this.itemCode} from ${this.fromLocation} to ${this.toLocation}`;
  }
}

/**
 * Stock adjustment error for inventory adjustments
 */
export class StockAdjustmentError extends StockError {
  public readonly itemCode: string;
  public readonly location: string;
  public readonly adjustmentType: AdjustmentType;
  public readonly adjustmentQuantity: number;
  public readonly currentQuantity: number;
  public readonly adjustmentReason?: string;

  constructor(
    itemCode: string,
    location: string,
    adjustmentType: AdjustmentType,
    adjustmentQuantity: number,
    currentQuantity: number,
    message: string,
    options?: AdjustmentOptions,
    context?: Record<string, any>
  ) {
    super(message, 'STOCK_ADJUSTMENT_FAILED', 400, context);
    this.name = 'StockAdjustmentError';
    this.itemCode = itemCode;
    this.location = location;
    this.adjustmentType = adjustmentType;
    this.adjustmentQuantity = adjustmentQuantity;
    this.currentQuantity = currentQuantity;
    if (options?.adjustmentReason !== undefined) this.adjustmentReason = options.adjustmentReason;
    Object.setPrototypeOf(this, StockAdjustmentError.prototype);
  }

  override toJSON() {
    return {
      ...super.toJSON(),
      itemCode: this.itemCode,
      location: this.location,
      adjustmentType: this.adjustmentType,
      adjustmentQuantity: this.adjustmentQuantity,
      currentQuantity: this.currentQuantity,
      adjustmentReason: this.adjustmentReason,
      projectedQuantity: this.getProjectedQuantity(),
      adjustmentDescription: this.getAdjustmentDescription()
    };
  }

  /**
   * Get projected quantity after adjustment
   */
  getProjectedQuantity(): number {
    switch (this.adjustmentType) {
      case 'increase':
        return this.currentQuantity + this.adjustmentQuantity;
      case 'decrease':
        return Math.max(0, this.currentQuantity - this.adjustmentQuantity);
      case 'recount':
        return this.adjustmentQuantity;
      default:
        return this.currentQuantity;
    }
  }

  /**
   * Get adjustment description
   */
  getAdjustmentDescription(): string {
    switch (this.adjustmentType) {
      case 'increase':
        return `Increase stock of ${this.itemCode} at ${this.location} by ${this.adjustmentQuantity} units`;
      case 'decrease':
        return `Decrease stock of ${this.itemCode} at ${this.location} by ${this.adjustmentQuantity} units`;
      case 'recount':
        return `Recount stock of ${this.itemCode} at ${this.location} to ${this.adjustmentQuantity} units`;
      default:
        return `Adjust stock of ${this.itemCode} at ${this.location}`;
    }
  }
}

/**
 * Stock tracking error for general tracking issues
 */
export class StockTrackingError extends StockError {
  public readonly itemCode: string;
  public readonly trackingId?: string;
  public readonly operationType: string;
  public readonly details: Record<string, any>;

  constructor(
    message: string,
    itemCode: string,
    operationType: string,
    details: Record<string, any> = {},
    options?: TrackingOptions,
    context?: Record<string, any>
  ) {
    super(message, 'STOCK_TRACKING_FAILED', 400, context);
    this.name = 'StockTrackingError';
    this.itemCode = itemCode;
    this.operationType = operationType;
    this.details = details;
    if (options?.trackingId !== undefined) this.trackingId = options.trackingId;
    Object.setPrototypeOf(this, StockTrackingError.prototype);
  }

  override toJSON() {
    return {
      ...super.toJSON(),
      itemCode: this.itemCode,
      operationType: this.operationType,
      details: this.details,
      trackingId: this.trackingId
    };
  }
}

