const { neon } = require('@neondatabase/serverless');
require('dotenv').config({ path: '/home/hein/Workspace/FF_Next.js/.env.local' });
const sql = neon(process.env.DATABASE_URL);

async function run() {
  // Summary stats per project per decision
  const rows = await sql\`
    SELECT 
      p.project_name,
      r.qa_decision,
      r.qa_decision_by,
      COUNT(*)::int as count,
      MIN(r.qa_decision_at) as earliest,
      MAX(r.qa_decision_at) as latest
    FROM construction_qa_reviews r
    JOIN projects p ON p.id = r.project_id
    WHERE r.project_id IN (
      '4eb13426-b2a1-472d-9b3c-277082ae9b55',
      'bf9a90db-e758-4c05-b999-694cd63c451f',
      '7003dc06-9af7-4a7c-bc6c-a177d77784f2'
    )
    AND r.qa_decision IS NOT NULL
    AND r.qa_decision_at >= NOW() - INTERVAL '30 days'
    GROUP BY p.project_name, r.qa_decision, r.qa_decision_by
    ORDER BY p.project_name, r.qa_decision, count DESC
  \`;

  console.log(JSON.stringify(rows, null, 2));
}
run().catch(e => console.error(e));
"
